const LEGEND_ORDER = { '1': ['corp', 'am', 'fio', 'fiz', 'skarb'], '2': ['corp', 'skarb', 'am', 'fio', 'fiz'], '3': ['fiz', 'am', 'fio', 'skarb', 'corp'], '4': ['corp', 'skarb', 'am', 'fio', 'fiz'] };

const saved = localStorage.getItem('ms-style');
const state = { style: ['2', '3', '4', 'makieta'].includes(saved) ? saved : '1', hot: null,
  currency: 'Łącznie', view: 'Aktywa',
  screen: 'pulpit', grouping: 'Emitenci', accounts: [],
  txTab: 'Wszystkie', txPeriod: '2026', txType: 'Wszystkie typy', txQuery: '',
  transit: false, seriesExpanded: false, lastAmounts: {} };

const pct = (n) => `${n.toFixed(1).replace('.', ',')}%`;
/* Makieta nie ma wlasnej palety — bierze nr 1, a kolor gasi CSS (--seg-flat).
   Kolejnosc pozycji ma taka jak nr 2. */
const pal = () => (state.style === '2' ? '2' : state.style === '3' ? '3' : state.style === '4' ? '4' : '1');
const ord = () => (state.style === '1' ? '1' : state.style === '3' ? '3' : state.style === '4' ? '4' : '2');
/* Nr 4 to nr 3 z innym portfelem i inna paleta. */
const isV3 = () => state.style === '3' || state.style === '4';
const dim = (id) => (state.hot === null ? '' : state.hot === id ? 'is-hot' : 'is-dim');
/* Licznik kwoty. Wersja preview przerysowuje cala strone, wiec poprzednia
   wartosc trzymamy w state.lastAmounts pod kluczem danego miejsca na ekranie —
   dzieki temu wiemy, ktore znaki naprawde sie zmienily. */
function roll(text, key) {
  const prev = state.lastAmounts[key];
  state.lastAmounts[key] = text;
  const was = prev === undefined ? null : [...prev];
  return [...text]
    .map((ch, i) => {
      const old = was ? was[i] : ch;
      const changed = was !== null && old !== ch;
      const delay = `animation-delay:${i * 18}ms`;
      return `<span class="roll">${
        changed ? `<span class="roll__out" aria-hidden="true" style="${delay}">${old === undefined ? '' : old}</span>` : ''
      }<span class="${changed ? 'roll__in' : ''}" style="${changed ? delay : ''}">${ch}</span></span>`;
    })
    .join('');
}

const amount = (int, dec, cls = '', key = '') =>
  `<div class="amount ${cls}"><span class="amount__int">${roll(int, key + '|int')}</span><span class="amount__dec">${roll(dec, key + '|dec')}</span></div>`;
const pills = (items, active, group) => {
  const locked = state.style === 'makieta';
  return `<div class="pills" role="group">${items
    .map((i) => `<button type="button" ${locked ? '' : `data-pill="${group}" `}data-value="${i}"
      aria-pressed="${i === active}"${locked ? ' aria-disabled="true"' : ''}>${i}</button>`)
    .join('')}</div>`;
};
const kv = (label, value, px = 0) =>
  `<div class="kv" style="--rowPx:${px}px"><span class="kv__label">${label}</span><span class="kv__value">${value}</span></div>`;


function chart(rows) {
  const segs = ordered(rows);
  const total = segs.reduce((acc, a) => acc + a.share, 0);
  return `<div class="chart" data-chart>${segs
    .map((s) => {
      const c = META[s.id].colors[pal()];
      return `<button type="button" class="chartSeg ${s.id === 'cash' ? 'chartSeg--cash' : ''} ${dim(s.id)}"
        data-hot="${s.id}" style="flex:${s.share / total} 1 0;--seg:${c.chart};--seg-foot:${c.chartFoot || c.chart}"
        aria-label="${META[s.id].name}: ${pct(s.share)}">
        <span class="chartSeg__body"></span><span class="chartSeg__foot"></span></button>`;
    })
    .join('')}</div>`;
}

function legendRow(r) {
  /* Ekran klasy aktywow istnieje tylko w stylistykach nr 1 i nr 2. */
  const link = state.style !== 'makieta' && DETAIL_ASSETS.has(r.id);
  return `<button type="button" class="legendRow ${dim(r.id)}" data-hot="${r.id}"
    ${link ? `data-open="${r.id}"` : ''} style="--seg:${META[r.id].colors[pal()].legend};cursor:${link ? 'pointer' : 'default'}">
    <span class="legendRow__dot"></span>
    <span class="legendRow__name">${META[r.id].name}</span>
    <span class="legendRow__share">${pct(r.share)}</span>
    <span class="legendRow__value">${r.value}</span></button>`;
}

function legend(rows, cashTooltip) {
  const all = ordered(rows);
  const cashRow = all.find((r) => r.id === 'cash');
  const tip = cashTooltip && state.style !== 'makieta';
  return `<div class="legend">
    <div class="legend__rows">${all.filter((r) => r.id !== 'cash').map(legendRow).join('')}</div>
    ${cashRow ? `<div class="legend__cash"><div class="legend__cashInner">
      <div class="${tip ? 'cashAnchor' : ''}">
      ${legendRow(cashRow)}
      ${tip ? `<div class="cashTip" role="tooltip">
        <span class="cashTip__title">${CASH_BY_CURRENCY.title}</span>
        <div class="cashTip__rows">${CASH_BY_CURRENCY.rows.map(([l, v]) => `<div class="cashTip__row">
          <span class="cashTip__label">${l}</span>
          <span class="cashTip__value">${v}</span></div>`).join('')}</div>
      </div>` : ''}
      </div>
      ${cashRow.sub ? `<div class="legend__cashSub ${dim('cash')}">${cashRow.sub}</div>` : ''}
    </div></div>` : ''}</div>`;
}

/* Karta z zerowym saldem nie niesie zadnej informacji. */
const isEmptyCash = (c) => String(c.amount).replace(/\s/g, '') === '0';

function cash(cards) {
  const visible = cards.filter((c) => !isEmptyCash(c));
  if (!visible.length) return '';
  return `<section class="cash">
    <h2 class="sectionTitle">Gotówka i środki rozliczeniowe</h2>
    <div class="cash__grid">${visible.map(
      (c, i) => {
        const link = state.style !== 'makieta' && state.currency === 'Łącznie'
          && c.label === 'Środki w drodze';
        return `<article class="cashCard ${link ? 'cashCard--link' : ''}" ${link ? 'data-open-drawer' : ''}>
        <div style="display:flex;flex-direction:column;gap:8px">
          <span class="cashCard__head"><span class="cashCard__label" style="flex:1">${c.label}</span>
            ${link ? '<span class="cashCard__chev">›</span>' : ''}</span>
          ${amount(c.amount, c.dec, 'cashCard__amount', 'gotowka-' + i)}
        </div>
        <div class="divider"></div>
        <div style="display:flex;flex-direction:column;gap:4px">
          ${c.rows.map(([l, v]) => kv(l, v)).join('')}
        </div></article>`;
      }
    ).join('')}</div></section>`;
}


