function accountCard(a) {
  return `<article class="acctCard" style="--seg:${a.marker[pal()]}">
    <div class="acctCard__head"><div class="acctCard__top">
      <div class="acctCard__title">
        <span class="acctCard__dot"></span>
        <span class="acctCard__name">${a.name}</span>
        <span class="acctCard__number">· ${a.number}</span>
      </div>
      ${amount(a.amount, a.dec, 'acctCard__amount', 'rachunek-' + a.id)}
    </div></div>
    ${a.strip ? `<div class="acctCard__limit">
        <span class="acctCard__limitLabel">${a.strip.label}</span>
        <div class="acctCard__limitTop">
          <span class="acctCard__limitValue">${a.strip.value}</span>
          ${a.strip.progress !== undefined
            ? `<span class="acctCard__limitPct">${Math.round(a.strip.progress * 100)}% wykorzystane</span>`
            : ''}
        </div>
        ${a.strip.progress !== undefined
          ? `<div class="acctCard__limitTrack"><div class="acctCard__limitFill"
               style="width:${a.strip.progress * 100}%"></div></div>`
          : ''}
      </div>` : ''}
    ${a.rows.length ? `<div class="divider"></div>
      ${isV3()
        ? `<div class="metrics">${a.rows.map(([l, v]) =>
            `<div class="metric"><span class="metric__label">${l}</span>
             <span class="metric__value">${v}</span></div>`).join('')}</div>`
        : `<div class="acctCard__rows">${a.rows.map(([l, v]) =>
            `<button type="button" class="acctRow"><span class="acctRow__label">${l}</span>
             <span class="acctRow__value">${v}</span><span class="acctRow__chev">›</span></button>`).join('')}
          </div>`}` : ''}
    <div class="acctCard__foot">
      <button type="button" class="acctCard__action" ${
        state.style !== 'makieta' && a.id === 'ike' && state.currency === 'Łącznie'
          ? 'data-goto-screen="account"' : ''}>${a.action}<span aria-hidden="true">›</span></button>
    </div></article>`;
}

function assetCard(a) {
  const makieta = state.style === 'makieta';
  const flat = state.style === '2' || isV3();
  const strip = !flat;
  const rows = makieta ? [] : strip ? a.rows : [...a.highlights, ...a.rows];
  const stripItems = makieta ? [...a.rows, ...a.highlights] : a.highlights;
  const link = DETAIL_ASSETS.has(a.id);
  return `<article class="assetCard ${link ? 'assetCard--link' : ''}" ${link ? `data-open="${a.id}"` : ''} style="--seg:${a.colors[pal()].card}">
    <div class="assetCard__head">
      <div class="assetCard__title">
        ${flat ? '<span class="assetCard__bar"></span>' : ''}
        <span class="assetCard__name">${a.name}</span>
        ${flat ? '' : '<span class="assetCard__dot"></span>'}
      </div>
      ${amount(makieta ? '≈ ' + a.amount : a.amount, a.dec, 'assetCard__amount', 'aktywo-' + a.id)}
    </div>
    ${makieta ? '' : '<div class="divider"></div>'}
    ${rows.length
      ? (isV3()
        ? `<div class="metrics">${rows.map(([l, v]) =>
            `<div class="metric"><span class="metric__label">${l}</span><span class="metric__value">${v}</span></div>`).join('')}</div>`
        : `<div class="assetCard__rows">${rows.map(([l, v]) => kv(l, v, strip ? 20 : 0)).join('')}</div>`)
      : ''}
    ${
      strip && stripItems.length
        ? `<div class="strip">${stripItems
            .map(([l, v]) => `<div class="strip__item"><span class="strip__label">${l}</span><span class="strip__value">${v}</span></div>`)
            .join('')}</div>`
        : ''
    }
    ${makieta ? `<div class="assetCard__more"><span class="acctCard__action">Zobacz szczegóły<span>›</span></span></div>` : ''}
    </article>`;
}


