/* toLocaleString nie grupuje czterocyfrowych liczb po polsku (9800, nie 9 800). */
const grosze = (n) => String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
const money = (n, unit) => `${grosze(n)},00 ${unit}`;
const pct2 = (n) => `${n.toFixed(2).replace('.', ',')}%`;
const partsOf = (i, acc) => i.parts.filter(([a]) => !acc.length || acc.includes(a));
const issuerValue = (i, acc) => partsOf(i, acc).reduce((s, [, v]) => s + v, 0);
const seriesOf = (i, acc) => [...new Set(partsOf(i, acc).flatMap(([, , se]) => se))];
const accountsIn = (v) => {
  const out = [];
  v.issuers.forEach((i) => i.parts.forEach(([a]) => { if (!out.includes(a)) out.push(a); }));
  return out;
};
const toDate = (s) => { const [d, m, y] = s.split('.').map(Number); return new Date(y, m - 1, d).getTime(); };

function classMetrics(view, acc) {
  const visible = view.issuers
    .map((i) => ({ issuer: i, value: issuerValue(i, acc) }))
    .filter((x) => x.value > 0);
  const total = visible.reduce((s, x) => s + x.value, 0);
  const serie = visible.reduce((s, x) => s + seriesOf(x.issuer, acc).length, 0);
  const wazona = total ? visible.reduce((s, x) => s + x.issuer.rate * x.value, 0) / total : 0;
  const odsetki = visible.reduce((s, x) => {
    const pelna = x.issuer.parts.reduce((a, [, v]) => a + v, 0) || 1;
    return s + Math.round((x.issuer.interest12m * x.value) / pelna);
  }, 0);
  const wykup = visible.map((x) => x.issuer.maturity).sort((a, b) => toDate(a) - toDate(b))[0];
  return { visible, total, rows: [
    ['Emitenci', String(visible.length)], ['Serie', String(serie)],
    ['Śr. rentowność (ważona)', pct2(wazona)],
    ['Wypłacone odsetki 12M', money(odsetki, view.unit)],
    ['Najbliższy wykup', wykup || '—'],
  ] };
}

function instrRow(it, withLabels, color) {
  const cells = [it.rate, it.maturity, it.share];
  /* Ekrany emitenta i serii istnieja tylko w stylistykach nr 1 i nr 2. */
  const target = state.style === 'makieta' ? null : state.grouping === 'Emitenci' ? 'issuer' : 'series';
  return `<button type="button" class="instrRow" ${
    target ? `data-goto-screen="${target}"` : ''} style="--seg:${color}">
    <span class="instrRow__dot"></span>
    <span class="instrRow__title">
      <span class="instrRow__name">${it.name}</span>
      <span class="instrRow__sub">${it.sub}</span>
    </span>
    <span class="instrRow__cols">${cells.map((v, i) => `<span class="instrRow__col">
      ${withLabels ? `<span class="instrRow__colLabel">${INSTRUMENT_COLS[i]}</span>` : ''}
      <span class="instrRow__colValue">${v}</span></span>`).join('')}</span>
    <span class="instrRow__value">${it.value}</span>
    <span class="instrRow__chev">›</span></button>`;
}

function txRows(all) {
  const allowed = TX_TAB_TYPES[state.txTab];
  const q = state.txQuery.toLowerCase();
  return all.filter((t) => {
    if (allowed && !allowed.includes(t[1])) return false;
    if (!t[0].endsWith(state.txPeriod)) return false;
    if (state.txType !== 'Wszystkie typy' && t[1] !== state.txType) return false;
    if (q && !t[2].toLowerCase().includes(q)) return false;
    return true;
  });
}

/* Na ekranie klasy aktywow rachunek ma wlasna kolumne, na wezszych ekranach
   schodzi pod nazwe instrumentu — tak jak w wireframe'ach. */
function transactions(all, noun, acc, total) {
  const rows = txRows(all);
  const columns = acc === 'column' ? TX_COLUMNS : TX_COLUMNS.slice(0, 5);
  const field = (label, cls, control) =>
    `<label class="field ${cls}"><span class="field__label">${label}</span>${control}</label>`;
  const select = (name, items, active) =>
    `<select class="field__control" data-select="${name}">${items
      .map((i) => `<option${i === active ? ' selected' : ''}>${i}</option>`).join('')}</select>`;

  return `<section class="panel">
    <div class="panel__head">
      <h2 class="sectionTitle">Transakcje</h2>
      <span class="panel__meta">${rows.length} ${noun}</span>
    </div>
    <div class="panel__toolbar">
      ${pills(TX_TABS, state.txTab, 'txtab')}
      ${total === undefined ? '' : `<div class="btnRow">
        <button type="button" class="btnGhost">Eksport PDF</button>
        <button type="button" class="btnGhost">Eksport XLS</button>
      </div>`}
    </div>
    <div class="filters">
      ${field('Okres', '', select('period', TX_PERIODS, state.txPeriod))}
      ${field('Typ transakcji', 'field--wide', select('type', TX_TYPES, state.txType))}
      ${field('Instrument', 'field--widest',
        `<input class="field__control" type="search" data-search placeholder="Szukaj instrumentu" value="${state.txQuery}">`)}
    </div>
    <div class="table ${acc === 'column' ? '' : 'table--narrow'}">
      <div class="table__head">${columns
        .map((c) => `<span class="table__th ${c === 'Kwota' ? 'is-right' : ''}">${c}</span>`).join('')}</div>
      ${rows.length === 0 ? '<div class="table__empty">Brak transakcji dla tych filtrów</div>' : ''}
      ${rows.map((t) => `<div class="table__row">
        <span class="table__td table__td--muted">${t[0]}</span>
        <span class="table__td">${t[1]}</span>
        <span class="table__td">${t[2]}${
          acc === 'subline' ? `<span class="table__note">${t[6]}</span>` : ''}</span>
        <span class="table__td is-right"><span class="table__amount">${t[3]}</span>
          ${t[4] ? `<span class="table__note">${t[4]}</span>` : ''}</span>
        <span class="table__td"><span class="badge">${t[5]}</span></span>
        ${acc === 'column' ? `<span class="table__td table__td--muted">${t[6]}</span>` : ''}
      </div>`).join('')}
      ${total === undefined ? '' : `<div class="table__foot">
        <button type="button" class="btnGhost">Pokaż kolejne 15 transakcji</button>
        <span class="table__caption">Wyświetlono ${rows.length} z ${total} transakcji</span>
      </div>`}
    </div></section>`;
}


