function ordered(rows) {
  const byId = Object.fromEntries(rows.map((r) => [r.id, r]));
  const out = LEGEND_ORDER[ord()].map((id) => byId[id]).filter(Boolean);
  if (byId.cash) out.push(byId.cash);
  return out;
}

